mapper.select:
SELECT t.product_type_id, tt.type as task_type, t.task_status, t.user_id FROM tb_task t LEFT JOIN tb_task_type tt ON t.product_type_id = tt.type_id
AND t.create_time >= #{start}
AND t.create_time <= #{end}

SELECT COUNT(*) as orderCount, SUM(amount) as orderAmount FROM tb_order
AND create_time >= #{start}
AND create_time <= #{end}
AND status IN (1, 2)

SELECT sku_name as skuName, SUM(quantity) as count FROM tb_order
AND create_time >= #{start}
AND create_time <= #{end}
AND status IN (1, 2)
GROUP BY sku_name ORDER BY count DESC LIMIT 10

SELECT DISTINCT o.region_name as regionName FROM tb_order o
AND o.create_time >= #{start}
AND o.create_time <= #{end}
AND o.status = 1 AND o.region_name IS NOT NULL
ORDER BY regionName

SELECT SUM(amount) as amount FROM tb_order o
AND o.create_time >= #{start}
AND o.create_time <= #{end}
AND o.status = 1 AND o.region_name IS NOT NULL
GROUP BY o.region_name ORDER BY o.region_name
